<div class="row g-2"><div class="col-md-6"><label class="form-label">Start date</label><input type="date" name="start_date" min="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-6"><label class="form-label">End date</label><input type="date" name="end_date" min="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-12"><fieldset><legend class="form-label mt-3">Operating weekdays</legend><?php foreach([1=>'Mon',2=>'Tue',3=>'Wed',4=>'Thu',5=>'Fri',6=>'Sat',7=>'Sun'] as $number=>$label):?><label class="me-2"><input type="checkbox" name="weekdays[]" value="<?=$number?>"> <?=$label?></label><?php endforeach;?></fieldset></div><div class="col-12"><label class="form-label mt-3">Maximum orders per entry</label><input type="number" name="capacity" min="0" max="1000" class="form-control" required></div></div>
